struct CaselessTurkicEntry
{
    std::uint32_t codepoint;
    std::uint32_t replacement;
};

inline constexpr CaselessTurkicEntry kCaselessTurkicTable[] = {
        {0x49, 0x131}, {0x130, 0x69}, {0x1D35, 0x131}, {0x2110, 0x131},
        {0x2111, 0x131}, {0x2160, 0x131}, {0x24BE, 0x131}, {0xFF29, 0x131},
        {0x1D408, 0x131}, {0x1D43C, 0x131}, {0x1D470, 0x131}, {0x1D4D8, 0x131},
        {0x1D540, 0x131}, {0x1D574, 0x131}, {0x1D5A8, 0x131}, {0x1D5DC, 0x131},
        {0x1D610, 0x131}, {0x1D644, 0x131}, {0x1D678, 0x131}, {0x1F138, 0x131},
};

inline constexpr std::size_t kCaselessCount =
    sizeof(kCaselessTable) / sizeof(kCaselessTable[0]);

inline constexpr std::size_t kCaselessTurkicCount =
    sizeof(kCaselessTurkicTable) / sizeof(kCaselessTurkicTable[0]);

inline const CaselessEntry *findCaseless(std::uint32_t codepoint)
{
    std::size_t low = 0;
    std::size_t high = kCaselessCount;
    while (low < high)
    {
        const std::size_t middle = low + (high - low) / 2;
        if (kCaselessTable[middle].codepoint < codepoint)
        {
            low = middle + 1;
        }
        else
        {
            high = middle;
        }
    }
    if (low < kCaselessCount && kCaselessTable[low].codepoint == codepoint)
    {
        return &kCaselessTable[low];
    }
    return nullptr;
}

inline const CaselessTurkicEntry *findCaselessTurkic(std::uint32_t codepoint)
{
    std::size_t low = 0;
    std::size_t high = kCaselessTurkicCount;
    while (low < high)
    {
        const std::size_t middle = low + (high - low) / 2;
        if (kCaselessTurkicTable[middle].codepoint < codepoint)
        {
            low = middle + 1;
        }
        else
        {
            high = middle;
        }
    }
    if (low < kCaselessTurkicCount && kCaselessTurkicTable[low].codepoint == codepoint)
    {
        return &kCaselessTurkicTable[low];
    }
    return nullptr;
}

